class Solution:
    def rotate(self, nums: List[int], k: int) -> None:
        """
        Do not return anything, modify nums in-place instead.
        """
        new_nums = []
        mod_k = len(nums) - (k % len(nums))
        for num in nums[mod_k:]:
            new_nums.append(num)
        for num in nums[:mod_k]:
            new_nums.append(num)
        for i, num in enumerate(new_nums):
            nums[i] = num
